function renderReportsView(){clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);S.n.metrics.append(metric("Previews",S.recentReports.length),metric("Salvos no Acervo",S.reportArchived?1:0),metric("Tipos",8),metric("Modo","Rascunho"));const form=E("form","ma-form","");form.appendChild(E("h2","","Relatorios"));const grid=E("div","ma-form-grid","");const type=E("label","","Tipo");const sel=E("select","");sel.name="report_type";["estoque","movimentacoes","inventario","conferencia","divergencia","prestacao_contas","termo_recebimento","administrativo"].forEach(v=>{const o=E("option","",label(v));o.value=v;sel.appendChild(o)});type.appendChild(sel);const unit=E("label","","Unidade autorizada");const unitSel=E("select","");unitSel.name="unit_id";overviewUnits().forEach(u=>{const o=E("option","",t(u.name)||u.id);o.value=u.id;unitSel.appendChild(o)});unit.appendChild(unitSel);const period=E("label","","Periodo");const p=E("input","");p.name="period";p.value="2026";period.appendChild(p);grid.append(type,unit,period);const save=E("button","ma-button","Gerar preview");save.type="submit";form.append(grid,save);form.onsubmit=e=>{e.preventDefault();generateReportPreview(form)};S.n.list.appendChild(form);if(S.reportError)S.n.list.appendChild(E("p","ma-error",S.reportError));renderReportDetail()}
function generateReportPreview(form){if(S.reportLoading)return;const p=readForm(form);S.reportLoading=true;S.reportError="";request("/reports/preview",{method:"POST",body:JSON.stringify(p)}).then(d=>{S.reportPreview=d.report||d.preview||d;S.recentReports.unshift(S.reportPreview);renderAll();msg("Preview gerado para revisao.","ok")}).catch(e=>{S.reportError=safeError(e,"Erro ao gerar relatorio.");renderAll()}).finally(()=>{S.reportLoading=false})}
function renderReportDetail(){if(!S.reportPreview){S.n.detail.appendChild(E("p","ma-empty","Gere um preview, revise e confirme o salvamento no Acervo."));return}const box=E("section","ma-detail-head","");box.appendChild(E("strong","",t(S.reportPreview.title)||"Relatorio municipal"));box.appendChild(E("span","ma-muted",[label(S.reportPreview.report_type),unitName(S.reportPreview.unit_id),t(S.reportPreview.period)].filter(Boolean).join(" - ")));box.appendChild(E("p","ma-muted",t(S.reportPreview.conclusion)||"Rascunho estruturado aguardando confirmacao humana."));const confirm=E("button","ma-button","Confirmar e salvar no Acervo");confirm.type="button";confirm.onclick=()=>archiveReport();box.appendChild(confirm);S.n.detail.appendChild(box)}
function archiveReport(){if(!S.reportPreview)return;request("/reports/archive",{method:"POST",body:JSON.stringify({report:S.reportPreview,confirmation:true,document_type:"relatorio",title:t(S.reportPreview.title)||"Relatorio municipal",unit_id:S.reportPreview.unit_id,operation_id:S.reportPreview.operation_id||S.reportPreview.id||"panel-preview"})}).then(d=>{S.reportArchived=d;msg("Relatorio salvo no Acervo.","ok");renderAll()}).catch(e=>msg(safeError(e,"Erro ao salvar no Acervo."),"error"))}
function renderAuditView(){clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);const rows=allShelfAudit();S.n.metrics.append(metric("Eventos",rows.length),metric("Movimentacoes",allMovements().length),metric("Ultima sync",S.assetLastSyncedAt?date(S.assetLastSyncedAt):"-"),metric("Falhas parciais",Object.values(S.shelfByUnit).filter(st=>st&&st.error).length));const panel=E("section","ma-panel","");panel.appendChild(E("h2","","Auditoria"));if(!rows.length)panel.appendChild(E("p","ma-empty","Nenhum evento de auditoria operacional carregado."));rows.forEach(a=>{const row=E("article","ma-row","");row.appendChild(E("strong","",t(a.action)||"Evento"));row.appendChild(E("span","",[t(a.user),date(a.created_at),t(a.summary),unitName(a.unit_id)].filter(Boolean).join(" - ")));panel.appendChild(row)});S.n.list.appendChild(panel);S.n.detail.appendChild(E("p","ma-muted","Auditoria consolidada a partir das fontes municipais ja carregadas no painel."))}
function openEloPanel(){S.eloOpen=true;S.view="elo";try{window.dispatchEvent(new CustomEvent("elo:open",{detail:{scope:"municipal",role:role(),institution:selectedInstitutionId()?"authorized":"none"}}))}catch(e){}renderAll()}
function renderEloView(){clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);S.n.metrics.append(metric("Contexto","Municipal"),metric("Unidades",overviewUnits().length),metric("Modo","Leitura"),metric("Chat",S.eloOpen?"Aberto":"Pronto"));const panel=E("section","ma-panel","");panel.appendChild(E("h2","","Assistente ELO"));panel.appendChild(E("p","ma-muted","O ELO sera aberto com o contexto municipal autorizado da sessao, sem informar IDs tecnicos manualmente."));const btn=E("button","ma-button","Perguntar ao ELO");btn.type="button";btn.onclick=openEloPanel;panel.appendChild(btn);S.n.list.appendChild(panel);S.n.detail.appendChild(E("p","ma-empty",S.eloOpen?"Contexto municipal autorizado. Use o chat ELO existente para consultar estoque, Sentinela, Acervo, patrimonio e auditoria.":"Clique para abrir o ELO sem duplicar chat."))}
function renderAll(){updateSession();renderNav();clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);if(S.view==="overview"){renderOverview();return}if(S.view==="assets"){renderAssetView();return}if(S.view==="documents"){renderDocumentView();return}if(S.view==="shelf"){renderMetrics();renderShelfView();return}if(S.view==="sentinel"){renderSentinelView();return}if(S.view==="reports"){renderReportsView();return}if(S.view==="profile-imports"){renderProfileImportReviewView();return}if(S.view==="audit"){renderAuditView();return}if(S.view==="notifications"){renderNotificationsView();return}if(S.view==="elo"){renderEloView();return}renderMetrics();renderList();renderDetail()}
function loadMe(){if(!token()){initialShell();if(canStartMunicipalDemo())return startMunicipalDemoSession();msg("Sessao expirada. Entre novamente para acessar o painel.","error");return Promise.resolve(false)}initialShell();msg("Validando sessao...","");return request("/me").then(d=>{S.me=d.me||{};if(!ACCESS_ROLES.includes(role())){msg("Acesso negado. Esta area administrativa nao esta disponivel para seu papel.","error");clear(S.n.metrics);clear(S.n.list);clear(S.n.detail);return false}if(role()==="leitura")S.view="overview";updateSession();return isPlatform()?loadInstitutions():loadOwnInstitution()}).catch(e=>{if(navigator.onLine===false&&restorePrivateSession())return true;msg(safeError(e,"Falha ao validar sessao."),"error");return false})}
function refreshCurrent(){return isPlatform()?loadInstitutions(S.selectedId):loadOwnInstitution()}
function loadInstitutions(keepId){if(!isPlatform())return Promise.resolve(false);msg("Carregando prefeituras...","");return request("/institutions").then(async d=>{S.institutions=d.institutions||[];S.selectedId=keepId&&S.institutions.some(i=>i.id===keepId)?keepId:(S.selectedId&&S.institutions.some(i=>i.id===S.selectedId)?S.selectedId:"");S.errors={};await Promise.all(S.institutions.map(inst=>loadUnitsFor(inst.id,true)));renderAll();savePrivateSession();msg("Lista atualizada.","ok");return true}).catch(e=>{msg(safeError(e,"Erro ao carregar prefeituras."),"error");renderAll();return false})}
function loadOwnInstitution(){const id=safeId(S.me&&S.me.institution_id);if(!id){msg("Sessao sem prefeitura vinculada.","error");renderAll();return Promise.resolve(false)}S.selectedId=id;msg("Carregando sua prefeitura...","");return request("/institutions/"+encodeURIComponent(id)).then(async d=>{S.institutions=[d.institution].filter(Boolean);S.errors={};await Promise.all([loadUnitsFor(id,false),loadUsersFor(id)]);renderAll();savePrivateSession();msg("Prefeitura carregada.","ok");return true}).catch(e=>{msg(safeError(e,"Erro ao carregar prefeitura."),"error");renderAll();return false})}
function loadUnitsFor(id,silent){const safe=safeId(id);if(!safe)return Promise.resolve(false);return request("/institutions/"+encodeURIComponent(safe)+"/units").then(d=>{S.unitsByInstitution[safe]=d.units||[];delete S.errors.units;return true}).catch(e=>{if(!silent)S.errors.units=safeError(e,"Falha ao carregar unidades.");return false})}
function loadUsersFor(id){const safe=safeId(id);if(!safe)return Promise.resolve(false);return request("/institutions/"+encodeURIComponent(safe)+"/users").then(d=>{S.usersByInstitution[safe]=d.users||[];delete S.errors.users;return true}).catch(e=>{S.usersByInstitution[safe]=S.usersByInstitution[safe]||[];S.errors.users=safeError(e,"Falha ao carregar usuarios.");return false})}
function openInstitution(id){const safe=safeId(id);if(!safe){msg("ID de prefeitura invalido.","error");return}if(!isPlatform()&&safe!==safeId(S.me&&S.me.institution_id)){msg("Acesso negado para outra prefeitura.","error");return}S.selectedId=safe;msg("Carregando prefeitura...","");request("/institutions/"+encodeURIComponent(safe)).then(d=>{const idx=S.institutions.findIndex(i=>i.id===safe);if(idx>=0)S.institutions[idx]=d.institution;else S.institutions.push(d.institution);renderAll();return Promise.all([loadUnitsFor(safe,false),loadUsersFor(safe)])}).then(()=>{renderAll();msg("Prefeitura aberta.","ok")}).catch(e=>{msg(safeError(e,"Erro ao abrir prefeitura."),"error");renderAll()})}
function deactivateInstitution(id){const safe=safeId(id);if(!safe||!canManageInstitutions())return;request("/institutions/"+encodeURIComponent(safe)+"/deactivate",{method:"POST"}).then(()=>loadInstitutions(safe)).then(()=>msg("Prefeitura desativada.","ok")).catch(e=>msg(safeError(e,"Erro ao desativar prefeitura."),"error"))}
function saveUnit(form,institutionId){if(S.saving||!canManageUnits())return;const p=readForm(form);const err=validateUnit(p);if(err){msg(err,"error");return}setSaving(form,true);request("/institutions/"+encodeURIComponent(safeId(institutionId))+"/units",{method:"POST",body:JSON.stringify(p)}).then(()=>Promise.all([loadUnitsFor(institutionId,false),loadUsersFor(institutionId)])).then(()=>{renderAll();msg("Unidade cadastrada.","ok")}).catch(e=>msg(safeError(e,"Erro ao salvar unidade."),"error")).finally(()=>setSaving(form,false))}
function updateUnit(form,id){if(S.saving||!canManageUnits())return;const p=readForm(form);const err=validateUnit(p);if(err){msg(err,"error");return}setSaving(form,true);request("/units/"+encodeURIComponent(safeId(id)),{method:"PATCH",body:JSON.stringify(p)}).then(()=>loadUnitsFor(S.selectedId,false)).then(()=>{renderAll();msg("Unidade atualizada.","ok")}).catch(e=>msg(safeError(e,"Erro ao atualizar unidade."),"error")).finally(()=>setSaving(form,false))}
function deactivateUnit(id){if(!canManageUnits())return;request("/units/"+encodeURIComponent(safeId(id))+"/deactivate",{method:"POST"}).then(()=>loadUnitsFor(S.selectedId,false)).then(()=>{renderAll();msg("Unidade desativada.","ok")}).catch(e=>msg(safeError(e,"Erro ao desativar unidade."),"error"))}
function createInvite(form,institutionId){if(S.saving||!canManageUsers())return;const p=readForm(form);if(!validEmail(p.email)){msg("E-mail obrigatorio e valido.","error");return}if(!inviteRoles().includes(p.role)){msg("Papel invalido.","error");return}const allowed=allowedUnitsFor(institutionId).map(u=>safeId(u.id));if(p.unit_id&& !allowed.includes(safeId(p.unit_id))){msg("Unidade nao autorizada para este convite.","error");return}setSaving(form,true);request("/institutions/"+encodeURIComponent(safeId(institutionId))+"/invites",{method:"POST",body:JSON.stringify(p)}).then(d=>{const panel=form.parentElement&&form.parentElement.querySelector("[data-invite-result]");if(panel)renderInviteToken(panel,d);msg("Convite criado.","ok")}).catch(e=>msg(safeError(e,"Erro ao criar convite."),"error")).finally(()=>setSaving(form,false))}
function updateUserRole(u,nextRole){if(!canActOnUser(u)||!inviteRoles().includes(nextRole)){msg("Papel nao permitido.","error");return}request("/users/"+encodeURIComponent(userId(u))+"/role",{method:"PATCH",body:JSON.stringify({role:nextRole})}).then(()=>loadUsersFor(S.selectedId)).then(()=>{renderAll();msg("Papel atualizado.","ok")}).catch(e=>msg(safeError(e,"Erro ao alterar papel."),"error"))}
function updateUserUnit(u,unitId){if(!canActOnUser(u)){msg("Usuario nao permitido.","error");return}const safe=safeId(unitId);const allowed=allowedUnitsFor(S.selectedId).map(unit=>safeId(unit.id));if(safe&& !allowed.includes(safe)){msg("Unidade nao autorizada.","error");return}request("/users/"+encodeURIComponent(userId(u))+"/units",{method:"PATCH",body:JSON.stringify({unit_id:safe})}).then(()=>loadUsersFor(S.selectedId)).then(()=>{renderAll();msg("Unidade do usuario atualizada.","ok")}).catch(e=>msg(safeError(e,"Erro ao alterar unidade."),"error"))}
function deactivateUser(u){if(!canActOnUser(u)){msg("Usuario nao permitido.","error");return}request("/users/"+encodeURIComponent(userId(u))+"/deactivate",{method:"POST"}).then(()=>loadUsersFor(S.selectedId)).then(()=>{renderAll();msg("Usuario desativado.","ok")}).catch(e=>msg(safeError(e,"Erro ao desativar usuario."),"error"))}
function openShelfUnitForTest(id){const inst=S.institutions.find(x=>x.id===S.selectedId);const safe=safeId(id);if(!inst||!safe){msg("Almoxarifado invalido.","error");return}const allowed=allowedUnitsFor(inst.id).map(u=>safeId(u&&u.id));if(!allowed.includes(safe)){msg("Acesso negado para almoxarifado.","error");return}S.openShelfUnitId=safe;ensureShelf(safe);renderAll()}
window.MunicipalAdminUi={init:loadMe,getStateForTest:()=>S,openInstitutionForTest:openInstitution,openShelfUnitForTest,openProfileImportForTest:loadProfileImport};
document.addEventListener("DOMContentLoaded",loadMe);
